/* Looking.
 * [MSG_LOOK 25 00 00] */
static void feather2_LookAtVine(void)
{
    feather2_Say(S_03FC, T_FEA2N000);
    feather2_Say(N_Lt_Stragey, T_FEA2_010);
    feather2_Say(N_Dr_McCoy, T_FEA2_005);
    return;
}

